  ($ec$602$ec$, $ec$กรณีฝากครรภ์ครั้งแรกอายุครรภ์ไม่เกิน 12 สัปดาห์  วันที่เข้ารับบริการก่อนวันสุดท้ายของการมีประจำเดือน$ec$, $ec$ให้ตรวจสอบวันที่เข้ารับบริการ เทียบกับวันสุดท้ายของการมีประจำเดือนต้องไม่เกิน 12 สัปดาห์ตามเงื่อนไขการจ่ายชดเชยค่าบริการ$ec$),
  ($ec$603$ec$, $ec$กรณีฝากครรภ์ครั้งแรก พบว่าอายุครรภ์มากกว่า 12 สัปดาห์  ( เทียบจากวันเข้ารับบริการกับวันสุดท้ายของการมีประจำเดือน)$ec$, $ec$กรณีฝากครรภ์ครั้งแรกอายุครรภ์ต้องไม่เกิน 12 สัปดาห์ตามเงื่อนไข$ec$),
  ($ec$604$ec$, $ec$ไม่บันทึกข้อมูล ว/ด/ป ที่คลอดบุตร$ec$, $ec$ให้บันทึก ว/ด/ป ที่คลอดบุตรให้ถูกต้องครบถ้วน$ec$),
  ($ec$605$ec$, $ec$กรณีตรวจหลังคลอด  พบว่าวันเข้ารับบริการตรวจหลังคลอดก่อนวันคลอดบุตร$ec$, $ec$ให้ตรวจสอบวันที่เข้ารับบริการ ต้องไม่ก่อนวันคลอดบุตร$ec$),
  ($ec$606$ec$, $ec$กรณีตรวจหลังคลอด พบว่าวันเข้าบริการตรวจหลังคลอด หลังวันคลอดบุตรมากกว่า 12 สัปดาห์   ( เทียบจากวันคลอดบุตร)$ec$, $ec$ให้ตรวจสอบวันที่เข้ารับบริการ และวันคลอดบุตรต้องไม่เกิน 12 สัปดาห์ตามเงื่อนไขการจ่ายชดเชยค่าบริการ$ec$),
  ($ec$607$ec$, $ec$กรณีส่งเสริมป้องกันโรคเลือกรายการที่ขอเบิกไม่สอดคล้องกับสิทธิ$ec$, $ec$เลือกรายการที่ขอเบิกให้ถูกต้อง  แล้วส่งเข้ามาใหม่$ec$),
  ($ec$608$ec$, $ec$กรณีส่งเสริมป้องกันโรค รายการที่ขอเบิกเป็นการให้บริการไม่สอดคล้องกับปีงบประมาณ$ec$, $ec$ให้ตรวจสอบรายการที่ขอเบิก   หรือวันที่เข้ารับบริการ แก้ไขให้ถูกต้องแล้วส่งเข้าใหม่ หรือ กรณีข้อมูลให้บริการตั้งแต่ปีงบ 55 ถึงปัจจุบันให้ส่งผ่าน OPPP Individual  Data$ec$),
  ($ec$609$ec$, $ec$เบิกกรณีส่งเสริมป้องกันโรค  แต่เลือกเงื่อนไขการเรียกเก็บเข้ามา$ec$, $ec$กรณีส่งเสริมป้องกันโรค  ไม่ต้องเลือกเงื่อนไขการเรียกเก็บ  แก้ไขให้ถูกต้องแล้วส่งเข้ามาใหม่$ec$),
  ($ec$610$ec$, $ec$รหัสโรค / รหัสหัตถการแพทย์แผนไทย บันทึกในหน้าผู้ป่วยในเท่านั้น$ec$, $ec$ตรวจสอบรหัสโรค/รหัสหัตถการที่ให้ กรณีรหัสโรค/รหัสหัตถการที่กำหนดในแพทย์แผนไทย บันทึกเบิกเป็นผู้ป่วยในเท่านั้น$ec$),
  ($ec$611$ec$, $ec$เบิกกรณี Palliative Care บันทึกรหัสโรครอง(Sdx) ไม่ถูกต้องตามเงื่อนไขที่กำหนด$ec$, $ec$ตรวจสอบการบันทึกรหัสโรคโรครอง (Sdx) กรณีดูแลผู้ป่วยระยะท้าย (Palliative Care)  Z515 ต้องเป็นโรคร่วม (Comorbility) เท่านั้น  แก้ไขแล้วส่งเข้ามาใหม่อีกครั้ง$ec$),
  ($ec$612$ec$, $ec$บันทึกรหัสโรคหลักและรหัสหัตถการไม่ถูกต้องกรณีเบิก Methadone$ec$, $ec$กรณีเบิก Methadone ตามสิทธิประโยชน์ที่ สปสช.กำหนด ได้เฉพาะโรค Pdx = F11.2
ICD9=9425 เท่านั้น ตรวจสอบและแก้ไขให้ถูกต้องแล้วส่งเข้ามาใหม่ หากไม่ตรงตามนี้ไม่สามารถเบิกกรณีนี้ได้$ec$),
  ($ec$613$ec$, $ec$เบิกกรณี Palliative Care ร่วมกับค่าใช้จ่ายสูง$ec$, $ec$ตรวจสอบการบันทึกข้อมูลกรณีการเยี่ยมบ้านในผู้ป่วยระยะท้ายไม่สามารถเบิกค่าใช้จ่ายสูง (HC)ได้$ec$),
  ($ec$614$ec$, $ec$เบิกกรณี Palliative Care บันทึกวันที่เยี่ยมบ้านก่อนเงื่อนไขที่กำหนด$ec$, $ec$ตรวจสอบวันที่เริ่มเยี่ยมบ้าน ดังนี้
1. ข้อมูลปี 60 เยี่ยมก่อนวันที่ 1 ก.ค 59 ไม่สามารถบันทึกเบิกกรณีนี้ได้
2. ข้อมูลปี 61 เยี่ยมก่อนวันที่ 1 เม.ย 60 ไม่สามารถบันทึกเบิกกรณีนี้ได้$ec$),
  ($ec$615$ec$, $ec$เบิกกรณี Palliative Care ในผู้ป่วยที่เสียชีวิตแล้ว$ec$, $ec$ตรวจสอบสิทธิ กรณีเสียชีวิตแล้วไม่สามารถบันทึกเบิกได้ หรือ ตรวจสอบวันที่ให้บริการแก้ไขให้ถูกต้องแล้วส่งเข้ามาใหม่อีกครั้ง$ec$),
  ($ec$616$ec$, $ec$รหัสโรคไม่สอดคล้องกับประเภทการยุติการตั้งครรภ์$ec$, $ec$ตรวจสอบรหัสเบิกกรณียุติการตั้งครรภ์และรหัสโรค แก้ไขให้ถูกต้องแล้วส่งเข้ามาใหม่อีกครั้ง$ec$),
  ($ec$617$ec$, $ec$รหัสหัตถการไม่สอดคล้องกับประเภทการยุติการตั้งครรภ์$ec$, $ec$ตรวจสอบรหัสเบิกกรณียุติการตั้งครรภ์และรหัสหัตถการ แก้ไขให้ถูกต้องแล้วส่งเข้ามมาใหม่อีกครั้ง$ec$),
  ($ec$618$ec$, $ec$บันทึกรหัสเบิกยุติการตั้งครรภ์ อายุน้อยกว่า 8 ปี$ec$, $ec$ตรวจสอบวัน เดือน ปี เกิด แก้ไขให้ถูกต้อง แล้วส่งเข้ามาใหม่ กรณีอายุไม่ถึง 8 ปี ไม่สามารถเบิกในรหัสยุติการตั้งครรภ์ได้$ec$),
  ($ec$619$ec$, $ec$เป็นหน่วยบริการปฐมภูมิ บันทึกรหัสเบิกยุติการตั้งครรภ์ หรือบันทึกรหัสบริการคุมกำเนิดกึ่งถาวร$ec$, $ec$หน่วยบริการปฐมภูมิไม่สามารถเบิก กรณียุติการตั้งครรภ์รหัส AB001,AB002,AB003 หรือบันทึกรหัสบริการคุมกำเนิดกึ่งถาวร (FP001,FP002)ได้$ec$),
  ($ec$620$ec$, $ec$ข้อมูลรับบริการ/จำหน่าย ก่อน วันที่ 1 ตุลาคม 2560 บันทึกเบิกกรณียุติการตั้งครรภ์$ec$, $ec$ตรวจสอบวันรับบริการ หรือ วันจำหน่าย แก้ไขให้ถูกต้อง แล้วส่งเข้ามาใหม่อีกครั้ง หากรับบริการ/จำหน่ายก่อน 1 ตุลาคม 2560 ไม่สามารถเบิกการยุติการตั้งครรภ์ได้$ec$),
  ($ec$621$ec$, $ec$การเบิกค่าตรวจสุขภาพประจำปี ข้อมูลเพศหรืออายุ ไม่สอดคล้องกับรหัสเบิกจ่าย (สิทธิ อปท./สิทธิ สปสช.)$ec$, $ec$ตรวจสอบข้อมูลเพศหรืออายุ ให้สอดคล้องกับรหัสเบิกจ่าย$ec$),
  ($ec$622$ec$, $ec$การเบิกค่าตรวจสุขภาพประจำปี ไม่ใช่สิทธิเจ้าตัว (สิทธิ อปท./สิทธิ สปสช.)$ec$, $ec$เบิกค่าตรวจสุขภาพประจำปี สิทธิ อปท.เบิกได้เฉพาะสิทธิเจ้าตัว$ec$),
  ($ec$623$ec$, $ec$การเบิกค่าตรวจสุขภาพประจำปี ครบตามอัตราที่กำหนดแล้ว (สิทธิ อปท./สิทธิ สปสช.)$ec$, $ec$ตรวจสอบการเบิกค่าตรวจสุขภาพประจำปี เบิกได้ไม่เกินอัตราที่กำหนด$ec$),
  ($ec$625$ec$, $ec$รหัสโรค/รหัสหัตถการไม่ตรงตามกลุ่ม One Day Surgery ที่กำหนด$ec$, $ec$ตรวจสอบรหัสหัตถการ (ICD9) แก้ไขให้ถูกต้องแล้วส่งเข้ามาใหม่ กรณีไม่ใช่กลุ่ม One Day Surgery ที่กำหนด บันทึกเบิกในหน้าผู้ป่วยนอก หรือ ผู้ป่วยใน (IPD) ปกติ$ec$),
  ($ec$626$ec$, $ec$ไม่ใช่หน่วยบริการที่ผ่านเกณฑ์การประเมิน One Day Surgery$ec$, $ec$บันทึกเบิกในหน้าผู้ป่วยนอก หรือ ผู้ป่วยใน (IPD) ปกติ$ec$),
  ($ec$627$ec$, $ec$บันทึกเป็นกรณี  One Day Surgery จำนวนวันนอนน้อยกว่า 2 ชั่วโมง หรือมากกว่า 24 ชั่วโมง$ec$, $ec$ตรวจสอบการบันทึก วันเวลา admit หรือ discharge  แก้ไขให้ถูกต้องแล้วส่งเข้ามาใหม่ กรณีวันนอนน้อยกว่า 2 ชั่วโมง หรือมากกว่า 24 ชั่วโมง บันทึกเบิกในหน้าผู้ป่วยนอก หรือ ผู้ป่วยใน (IPD) ปกติ$ec$),
  ($ec$628$ec$, $ec$บันทึกเป็นกรณี One Day Surgery แต่ผู้ป่วยมีภาวะแทรกซ้อน$ec$, $ec$ตรวจสอบการบันทึกรหัสโรค รหัสหัตถการ แก้ไขแล้วส่งเข้ามาใหม่ กรณีมีภาวะแทรกซ้อน บันทึกเบิกในหน้าผู้ป่วยนอก หรือ ผู้ป่วยใน (IPD) ปกติ$ec$),
  ($ec$629$ec$, $ec$บันทึกเป็นกรณี One Day Surgery ประเภทการจำหน่ายไม่ใช่ 1 Improve$ec$, $ec$ตรวจสอบการบันทึกประเภทการจำหน่ายแก้ไขให้ถูกต้องแล้วส่งเข้ามาใหม่ กรณีประเภทการจำหน่ายไม่ใช่ 1 Improve  บันทึกเบิกในหน้าผู้ป่วยนอก หรือ ผู้ป่วยใน (IPD) ปกติ$ec$),
  ($ec$630$ec$, $ec$ไม่ใช่กลุ่มเป้าหมายผู้รับบริการ (อายุต่ำกว่า 35 ปี) บริการคัดกรองเบาหวาน/ความดันโลหิตสูงและปัจจัยเสี่ยงต่อการเกิดโรคหัวใจและหลอดเลือด$ec$, $ec$ตรวจสอบอายุของผู้รับบริการเฉพาะประชาชนไทย สิทธิ์ UC  ที่มีอายุ 35 ปีขึ้นไป$ec$),
  ($ec$631$ec$, $ec$ไม่ใช่ข้อมูลที่ให้บันทึกเบิกในโปรแกรม e-Claim สำหรับหน่วยบริการเขต กทม./รัฐสังกัด สป.สธ.$ec$, $ec$หน่วยบริการในเขต 13 ให้บันทึกเบิกในโปรแกรม BPPDS$ec$),
  ($ec$632$ec$, $ec$เคยได้รับการวินิจฉัยเบาหวาน/ความดันโลหิตสูง /ความเสียงโรคหัวใจ$ec$, $ec$ตรวจสอบการบันทึกเบิกบริการคัดกรองเบาหวาน/ความดันโลหิตสูงและปัจจัยเสี่ยงต่อการเกิดโรคหัวใจและหลอดเลือด ต้องเป็นผู้ที่ไม่เคยได้รับการวินิจฉัยเบาหวาน/ความดันโลหิตสูง /ความเสียงโรคหัวใจ มาก่อน$ec$),
  ($ec$633$ec$, $ec$บันทึกเบิกกรณี.ฝากครรภ์เกินจำนวนครั้งที่กำหนด$ec$, $ec$การรับบริการและเบิกกรณีฝากครรภ์ไม่เกิน 5 ครั้ง/คน/ปีงบประมาณ$ec$),
  ($ec$634$ec$, $ec$กรณีการฝากครรภ์บันทึกเบิกการตรวจอัลตราซาวด์มากกว่า 1 ครั้ง/การตั้งครรภ์$ec$, $ec$ตรวจสอบการบันทึกรหัสหัตถการการทำอัลตราซาวด์ กรณีการฝากครรภ์เบิกได้ 1 ครั้ง/การตั้งครรภ์ ตัดรหัสหัตถการที่เกี่ยวข้องออกเพื่อรับค่าใช้จ่ายอื่นตามเงื่อนไขที่กำหนด แล้วส่งเข้ามาใหม่อีกครั้ง$ec$),
  ($ec$635$ec$, $ec$บันทึกเบิกกรณีบริการตรวจสุขภาพช่องปากและขัดทำความสะอาดฟันแต่ไม่ใช่หญิงตั้งครรภ์$ec$, $ec$การเบิกกรณีบริการตรวจสุขภาพช่องปากและขัดทำความสะอาดฟัน เบิกได้ในหญิงตั้งครรภ์เท่านั้น ตรวจสอบรหัสหัตถการ แก้ไขหรือตัดออกเพื่อรับค่าบริการกรณีอื่นๆ ตามเงื่อนไขที่กำหนด แล้วส่งเข้ามาใหม่อีกครั้ง$ec$),
  ($ec$636$ec$, $ec$บันทึกเบิกกรณีในการขัดและทำความสะอาดฟันไม่พบหัตถการที่กำหนด$ec$, $ec$ตรวจสอบการบันทึกรหัสหัตถการบันทึก หรือแก้ไขให้ถูกต้องแล้วส่งเข้ามาใหม่อีกครั้ง$ec$),
  ($ec$637$ec$, $ec$บันทึกข้อมูลเบิกกรณีฝากครรภ์หรือกรณีคัดกรองมะเร็งปากมดลูก ไม่ครบถ้วนตามเงื่อนไขที่กำหนด$ec$, $ec$ตรวจสอบการบันทึกเพศเบิกกรณีฝากครรภ์/คัดกรองมะเร็งปากมดลูกต้องเป็นเพศหญิงเท่านั้น แก้ไขแล้วส่งเข้ามาใหม่อีกครั้ง$ec$),
  ($ec$638$ec$, $ec$กรณีตรวจคัดกรองมะเร็งปากมดลูกอายุน้อยกว่า 15 ปี หรือมากกว่า 60 ปี$ec$, $ec$ตรวจสอบวัน เดือน ปี เกิด แก้ไขให้ถูกต้อง แล้วส่งเข้ามาใหม่ กรณีอายุไม่ตรงตามเงื่อนไขที่กำหนดในแต่ละปีงบประมาณไม่สามารถเบิกกรณีตรวจคัดกรองมะเร็งปากมดลูก ได้$ec$),
